import * as fs from 'fs';
import { PromiseUtils } from 'jibo-cai-utils';


export class FileUtils {
    static async readJSON(path: string): Promise<any> {
        const fileString = await PromiseUtils.promisify<string>(cb => fs.readFile(path, 'utf8', cb));
        try {
            return JSON.parse(fileString);
        } catch (error) {
            throw new Error(`Error when parsing '${path}': ${error.message}`);
        }
    }
}