const uuid = require('uuid');

/**
 * Return a promise when will be resolved after a specified amount of milliseconds.
 * Useful to delay execution of an async function
 * @param timeout Milliseconds to delay
 */
export function delay(timeout: number): Promise<void> {
    return new Promise(resolve =>
        setTimeout(resolve, timeout)
    );
}

/**
 * Measures the time it takes to perform an async operation and returns the
 * async return value as well as the time in milliseconds.
 */
export async function time<T>(promise: Promise<T>): Promise<[T, number]> {
    const start = Date.now();
    return promise.then(data => {
        const time = Date.now() - start;
        return <[T, number]>[data, time];
    });
}

/**
 * Gets string error message from any error type
 * @param e String, Error or any other object
 */
export function getErrorMessage(e: any): string {
    if (typeof e === 'string') {
        return e;
    } else if (typeof e.message === 'string') {
        return e.message;
    } else {
        return 'Error: ' + JSON.stringify(e);
    }
}

export function getUUID(): string {
    return uuid.v4();
}
