/**
 * Applies Object.freeze to the passed object 
 * and to all its complex properties recursively 
 */
export function deepFreeze<T>(obj: T): T {
    Object.freeze(obj);
    if (obj === undefined) {
        return obj;
    }

    Object.getOwnPropertyNames(obj).forEach(function (prop) {
        const v = obj[prop];
        if (v !== null
                && (typeof v === 'object' || typeof v === 'function')
                && !Object.isFrozen(v)) {
            deepFreeze(v);
        }
    });

    return obj;
}

/**
 * Deep Object.assign.
 * Explicit type casts are safe because function implementation guarantees type safety
 */
export function deepMerge<T>(left: T, right: Partial<T> | T): T {
    if (typeof left !== 'object' || left === null) {
        return (typeof right === 'undefined' ? left : right) as T;
    }

    const result = { ...(left as any) };

    if (typeof right === 'object' && right !== null) {
        Object.keys(right).forEach(key => {
            result[key] = deepMerge(left[key], right[key]);
        });
    }

    return result as T;
}

/**
 * Gets object property when path is a string like "person.address.id"
 * @returns Undefined if path does not exist
 */
export function getObjectProperty(obj: object, path: string): any {
    const pathPieces = path.split('.');
    return pathPieces.reduce((acc, current) => {
        if (typeof acc === 'object' && acc !== null) {
            // return deeper object
            return acc[current];
        } else {
            return undefined;
        }
    }, obj);
}