export type EventDataHandler<T> = (data: T) => void;

/**
 * A typed event provider. Subscribers can register handlers for the event.
 */
export abstract class EventProvider<EventType> {

    private _handlers: EventDataHandler<EventType>[] = []; 

    onEvent(handler: EventDataHandler<EventType>) {
        this._handlers.push(handler);
    }

    emit(data: EventType) {
        this._handlers.forEach(h => h(data));
    }
} 
